args.sparql:
SELECT ?youngerFilm ?youngerDirector ?bdate ?youngerLabel WHERE {
  dbr:College_Lovers dbo:director ?d1 .
  ?d1 dbo:birthDate ?b1 .
  dbr:The_Dixie_Flyer dbo:director ?d2 .
  ?d2 dbo:birthDate ?b2 .
  {
    FILTER(?b1 > ?b2)
    BIND(dbr:College_Lovers AS ?youngerFilm)
    BIND(?d1 AS ?youngerDirector)
    BIND(?b1 AS ?bdate)
  }
  UNION
  {
    FILTER(?b2 > ?b1)
    BIND(dbr:The_Dixie_Flyer AS ?youngerFilm)
    BIND(?d2 AS ?youngerDirector)
    BIND(?b2 AS ?bdate)
  }
  OPTIONAL { ?youngerFilm rdfs:label ?youngerLabel FILTER(lang(?youngerLabel)='en') }
}

SELECT ?director ?directorLabel WHERE {
  dbr:College_Lovers dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
}

SELECT ?director ?directorLabel WHERE {
  dbr:The_Dixie_Flyer dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
}

SELECT ?director ?directorLabel WHERE {
  dbr:The_Dixie_Flyer dbp:director ?dirVal .
  BIND(STR(?dirVal) AS ?dirStr) .
  OPTIONAL { ?dirVal rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
  BIND(COALESCE(?dirVal, ?dirStr) AS ?director)
}

