PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?youngerFilm ?label WHERE {
  {
    SELECT(xsd:integer(SUBSTR(STR(?b1) , 1 , 4)) AS ?y1)(xsd:integer(SUBSTR(STR(?b2) , 1 , 4)) AS ?y2) WHERE {
      dbr:John_G._Adolfi dbo:birthDate ?b1 .
      dbr:Charles_J._Hunt dbo:birthDate ?b2 .
    }
  }
  BIND(IF(?y1 > ?y2 , dbr:College_Lovers , dbr:The_Dixie_Flyer) AS ?youngerFilm)
  OPTIONAL {
    ?youngerFilm rdfs:label ?label
    FILTER(lang(?label) = 'en')
  }
}

